-- Permanent identity and native conditional combat/movement effects.
-- Add to, rather than replace, the inherited Barracks values.
UPDATE Building_YieldChanges SET Yield=Yield+1 WHERE BuildingType='BUILDING_T1Z_HEADQUARTERS' AND YieldType='YIELD_CULTURE';
 SELECT 'BUILDING_T1Z_HEADQUARTERS','YIELD_CULTURE',1 WHERE NOT EXISTS
 (SELECT 1 FROM Building_YieldChanges WHERE BuildingType='BUILDING_T1Z_HEADQUARTERS' AND YieldType='YIELD_CULTURE');
UPDATE Unit_ProductionModifierBuildings SET ProductionModifier=ProductionModifier+10
 WHERE BuildingType='BUILDING_T1Z_HEADQUARTERS' AND UnitType IN (SELECT u.Type FROM Units u WHERE u.Domain='DOMAIN_LAND'
 AND u.Combat>0 AND COALESCE(u.RangedCombat,0)=0
 AND NOT EXISTS (SELECT 1 FROM Unit_FreePromotions f JOIN UnitPromotions p ON p.Type=f.PromotionType
                 WHERE f.UnitType=u.Type AND p.OnlyDefensive=1));
 SELECT Type,'BUILDING_T1Z_HEADQUARTERS',10 FROM Units WHERE Type IN (SELECT u.Type FROM Units u WHERE u.Domain='DOMAIN_LAND'
 AND u.Combat>0 AND COALESCE(u.RangedCombat,0)=0
 AND NOT EXISTS (SELECT 1 FROM Unit_FreePromotions f JOIN UnitPromotions p ON p.Type=f.PromotionType
                 WHERE f.UnitType=u.Type AND p.OnlyDefensive=1)) AND NOT EXISTS
 (SELECT 1 FROM Unit_ProductionModifierBuildings b WHERE b.BuildingType='BUILDING_T1Z_HEADQUARTERS' AND b.UnitType=Units.Type);
UPDATE Leader_Flavors SET Flavor=9 WHERE LeaderType='LEADER_T1Z_FAKER' AND FlavorType IN ('FLAVOR_OFFENSE','FLAVOR_MILITARY_TRAINING');
UPDATE Leader_Flavors SET Flavor=7 WHERE LeaderType='LEADER_T1Z_FAKER' AND FlavorType='FLAVOR_CULTURE';
